(function(){'use strict';const C=window.PhysicsScenarioCourse,H=C.helpers;const cases=[{"target": "static-equilibrium-focus-1", "sourceID": "PHY-BOOK-Q081", "label": "WATP 2022, imported exam-book question 3 (Principles of Moments and Equilibrium)", "title": "Tray tipping", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q081-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 81, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2022, imported exam-book question 3 (Principles of Moments and Equilibrium)</b></p><p><b>Step 1.</b> Recognise the threshold: the tray is just about to rotate about the bench edge. The reaction there has zero moment, so choose that edge as pivot.</p><p><b>Step 2.</b> The image gives 37.0 cm of the 54.0 cm tray inside the bench, leaving 17.0 cm overhanging. The uniform tray COM is 27.0 cm from its end, therefore 10.0 cm inside the edge. The drink sits x outside the edge.</p><p><b>Step 3.</b> Opposite moments balance at threshold: 0.290gx = 0.370g × 0.100. Cancel g, divide by 0.290, and obtain x = 0.1276 m = 12.8 cm. Beyond that distance the drink moment wins. The question seeks a threshold, not an arbitrary stable placement.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>—</td><td>The tray centre is 27.0 cm from its end; its overhang is 17.0 cm, placing its centre 10.0 cm inside the bench edge.</td><td>1</td></tr><tr><td>—</td><td>At tipping, 0.290gx = 0.370g(0.100).</td><td>1</td></tr><tr><td>—</td><td>x = 0.1276 m = 12.8 cm outside the edge; slightly more than this causes instability.</td><td>1</td></tr></tbody></table></div>"}, {"target": "inclined-planes-focus-1", "sourceID": "PHY-BOOK-Q034", "label": "WATP 2020, imported exam-book question 34 (Electromagnetism)", "title": "Slope reversal and velocity graph", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q034-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 34, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q034-02.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 34, section 2: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2020, imported exam-book question 34 (Electromagnetism)</b></p><p><b>Step 1.</b> Use uphill as positive. In the simplified translational model expected by this paper, the only along-slope force is the downhill component of weight. Rotational energy and rolling friction are neglected; a real rolling solid ball can have a different acceleration.</p><p><b>Step 2.</b> Resolve weight: Fparallel = −mg sin8.00°. Newton’s law gives a = −g sin8.00° = −1.36 m/s². Mass cancels; the negative sign means downhill, even while velocity initially points uphill.</p><p><b>Step 3.</b> Read graph 4 in the source: a straight descending velocity line crosses zero then becomes negative. Its slope stays negative through the turn. Graphs returning to zero without negative velocity do not represent the ball returning downhill.</p><p><b>Source note.</b> This source item is misplaced in the electromagnetism chapter; it is indexed under motion on inclined planes. Treat the ball as a particle as intended; rolling inertia is unspecified.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Resolve weight down the incline: Fparallel = mg sin 8.00°.</td><td>1</td></tr><tr><td>a</td><td>Apply Fparallel = ma, so a = g sin 8.00°.</td><td>1</td></tr><tr><td>a</td><td>a = 1.36 m s⁻² down the slope.</td><td>1</td></tr><tr><td>b</td><td>Choose graph 4: velocity decreases linearly with time.</td><td>1</td></tr><tr><td>b</td><td>Acceleration is constant and down the incline during both upward and downward motion.</td><td>1</td></tr><tr><td>b</td><td>Velocity crosses zero at the turning point, then becomes negative for downward motion.</td><td>1</td></tr></tbody></table></div>"}, {"target": "grav-fields-focus-3", "sourceID": "PHY-BOOK-Q060", "label": "WATP 2023, imported exam-book question 2 (Satellite Motion)", "title": "Two-body gravitational force ratio", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q060-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 60, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 2 (Satellite Motion)</b></p><p><b>Step 1.</b> The satellite lies between Jupiter and Ganymede. The forces oppose each other, so compare magnitudes rather than adding them. Use centre-to-centre distances: 0.75R to Jupiter and 0.25R to Ganymede.</p><p><b>Step 2.</b> Write FJ = GMJm/(0.75R)² and FG = GMGm/(0.25R)². Divide before inserting huge numbers: G, satellite mass m and R² cancel.</p><p><b>Step 3.</b> FJ/FG = (1.90 × 10²⁷ / 1.48 × 10²³)(0.25/0.75)² = 1.43 × 10³. Jupiter’s force dominates, so acceleration points toward Jupiter. Use the supplied source data, even though the printed orbital distance is not a reliable astronomical value; it cancels from this ratio.</p><p><b>Source note.</b> The source’s 628 million km Ganymede orbital radius is erroneous; the force ratio is independent of its value, so the intended ratio result is unaffected.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>—</td><td>Distances to Jupiter and Ganymede are 0.75R and 0.25R respectively.</td><td>1</td></tr><tr><td>—</td><td>F = GMm/r² for each body.</td><td>1</td></tr><tr><td>—</td><td>FJ/FG = (MJ/MG)(0.25/0.75)².</td><td>1</td></tr><tr><td>—</td><td>Ratio = (1.90 × 10²⁷/1.48 × 10²³)/9 ≈ 1.43 × 10³:1.</td><td>1</td></tr><tr><td>—</td><td>The much larger Jupiter force gives net acceleration toward Jupiter.</td><td>1</td></tr></tbody></table></div>"}, {"target": "grav-energy-focus-1", "sourceID": "PHY-BOOK-Q122", "label": "WATP 2023, imported exam-book question 2 (Comprehension)", "title": "Potential energy and escape comprehension", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q122-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 122, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q122-02.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 122, section 2: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q122-03.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 122, section 3: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q122-04.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 122, section 4: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 2 (Comprehension)</b></p><p><b>Step 1.</b> Use the supplied reading as a model-building exercise. U = mgh assumes approximately constant g over a small height change. For large radial changes adopt U = −GMm/r and explicitly set zero at infinity. A zero reference changes energy labels, not forces.</p><p><b>Step 2.</b> For outward motion r₂ &gt; r₁: ΔU = GMm(1/r₁ − 1/r₂) &gt; 0. Draw U below zero, rising asymptotically toward zero; the threshold escape kinetic-energy curve has equal and opposite value, keeping total energy zero.</p><p><b>Step 3.</b> At minimum escape speed, final speed tends to zero at infinity. Set ½mv² − GMm/R = 0, cancel m and obtain v = √(2GM/R). Earth gives 11.2 km/s. The Moon has smaller M/R, hence smaller escape speed. This does not mean gravity abruptly switches off at a finite distance.</p><p><b>Step 4.</b> Voyager distance is 158 × 1.50 × 10¹¹ = 2.37 × 10¹³ m. Remaining potential-energy gain due to Earth alone is 0 − U = GMEm/r = 1.21 × 10⁴ J. This calculation deliberately excludes the Sun and other bodies. The source’s phrase that both energies approach zero applies to threshold escape, not every escaping launch.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Ep = mgh assumes g is essentially constant, valid only over small height changes near a surface.</td><td>1</td></tr><tr><td>a</td><td>Gravitational field weakens with distance; “height” and the potential-energy zero must be specified, so mgh is not an absolute universal potential.</td><td>1</td></tr><tr><td>b</td><td>Use U = −GMm/r with zero at infinity.</td><td>1</td></tr><tr><td>b</td><td>For motion farther away, r₂ &gt; r₁ so ΔU = GMm(1/r₁ − 1/r₂).</td><td>1</td></tr><tr><td>b</td><td>1/r₁ &gt; 1/r₂, hence ΔU &gt; 0.</td><td>1</td></tr><tr><td>c</td><td>Draw a negative potential-energy curve increasing with radius.</td><td>1</td></tr><tr><td>c</td><td>Its shape is −GMm/r and approaches zero asymptotically from below as r → ∞.</td><td>1</td></tr><tr><td>d</td><td>At escape threshold ½mv² = GME m/RE.</td><td>1</td></tr><tr><td>d</td><td>vescape = √(2GME/RE).</td><td>1</td></tr><tr><td>d</td><td>vescape = 1.12 × 10⁴ m s⁻¹ = 11.2 km s⁻¹.</td><td>1</td></tr><tr><td>e</td><td>Escape speed from the Moon is smaller.</td><td>1</td></tr><tr><td>e</td><td>vescape² is proportional to M/R.</td><td>1</td></tr><tr><td>e</td><td>Moon mass is about 0.0123 Earth masses while its radius is about 0.273 Earth radii.</td><td>1</td></tr><tr><td>e</td><td>Thus its M/R is much smaller and less energy per unit mass is needed to escape.</td><td>1</td></tr><tr><td>f</td><td>r = 158 × 1.50 × 10¹¹ = 2.37 × 10¹³ m.</td><td>1</td></tr><tr><td>f</td><td>Remaining increase to infinity is 0 − U(r) = GME m/r.</td><td>1</td></tr><tr><td>f</td><td>Substitute ME = 5.97 × 10²⁴ kg and m = 722 kg.</td><td>1</td></tr><tr><td>f</td><td>ΔU = 1.21 × 10⁴ J ≈ 12 kJ due to Earth alone.</td><td>1</td></tr></tbody></table></div>"}, {"target": "circular-focus-2", "sourceID": "PHY-BOOK-Q065", "label": "WATP 2022, imported exam-book question 3 (Circular Motion)", "title": "Conical pendulum geometry", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q065-01.jpg\" width=\"868\" height=\"1155\" alt=\"Original question 65, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2022, imported exam-book question 3 (Circular Motion)</b></p><p><b>Step 1.</b> The original drawing marks θ to the vertical. The horizontal path radius is 1.10 m; string length 4.00 m is not that radius. Geometry gives sinθ = r/L = 0.275, so θ = 16.0°.</p><p><b>Step 2.</b> Use different symbols for tension Fstring and period T. Vertical acceleration is zero: Fstring cosθ = mg. Horizontal inward resultant is Fstring sinθ = mv²/r. Divide to remove tension and mass: tanθ = v²/(rg).</p><p><b>Step 3.</b> Insert v = 2πr/T. Rearranging gives T = 2π√[r/(g tanθ)] = 2π√(L cosθ/g) = 3.94 s. This is a period, not a frequency; its units are seconds.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>—</td><td>Geometry: sin θ = r/L = 1.10/4.00.</td><td>1</td></tr><tr><td>—</td><td>θ = 16.0° to the vertical.</td><td>1</td></tr><tr><td>—</td><td>Vertical equilibrium: tension cos θ = mg.</td><td>1</td></tr><tr><td>—</td><td>Horizontal force: tension sin θ = mv²/r, hence tan θ = v²/(rg).</td><td>1</td></tr><tr><td>—</td><td>Using v = 2πr/T gives T = 2π√[r/(g tan θ)] = 2π√(L cos θ/g).</td><td>1</td></tr><tr><td>—</td><td>T = 3.94 s.</td><td>1</td></tr></tbody></table></div>"}, {"target": "orbits-focus-1", "sourceID": "PHY-BOOK-Q095", "label": "WATP 2022, imported exam-book question 1 (Universal Law of Gravitation)", "title": "Comparing moons of Jupiter", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q095-01.jpg\" width=\"868\" height=\"1124\" alt=\"Original question 95, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2022, imported exam-book question 1 (Universal Law of Gravitation)</b></p><p><b>Step 1.</b> Both moons orbit the same central planet, so Kepler’s ratio removes the planet mass and G. Assume approximately circular orbits and negligible moon masses.</p><p><b>Step 2.</b> TC²/rC³ = TG²/rG³ implies rG = rC(TG/TC)^(2/3). Keep both periods in days because this is a ratio; keep radius in kilometres if that is the requested answer.</p><p><b>Step 3.</b> rG = 1.88 × 10⁶(7.17/17.0)^(2/3) = 1.06 × 10⁶ km. A shorter period should give a smaller radius, which is a useful check before accepting the calculator result.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>—</td><td>For moons orbiting the same planet, T²/r³ is constant.</td><td>1</td></tr><tr><td>—</td><td>rG = rC(TG/TC)^(2/3).</td><td>1</td></tr><tr><td>—</td><td>Substitute rC = 1.88 × 10⁶ km, TG = 7.17 d and TC = 17.0 d.</td><td>1</td></tr><tr><td>—</td><td>rG = 1.06 × 10⁶ km.</td><td>1</td></tr></tbody></table></div>"}, {"target": "relativity-foundations-focus-2", "sourceID": "PHY-BOOK-Q114", "label": "WATP 2021, imported exam-book question 4 (Special Relativity)", "title": "Train simultaneity and contraction", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q114-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 114, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2021, imported exam-book question 4 (Special Relativity)</b></p><p><b>Step 1.</b> Read the image: Delta is at the western/rear end and Liam at the eastern/front end. Interpret the paper’s simultaneous events as simultaneous emissions in Nancy’s platform frame; distinguish emission time from the time light is received.</p><p><b>Step 2.</b> In Nancy’s frame the light from each end travels at c. Minh moves east toward the incoming light from Liam and away from the light emitted by Delta, so she receives Liam’s light first: option B. Equal distances in the train frame do not establish simultaneous emission in that frame.</p><p><b>Step 3.</b> For the length calculation, the carriage is at rest with Minh: L₀ = 20.0 m. The platform is at rest with Nancy; her 10.0 m platform is not contracted in her own frame. She measures the moving carriage as 10.0 m.</p><p><b>Step 4.</b> L/L₀ = √(1 − v²/c²) = 0.500 gives v/c = √0.750 = 0.866, hence v = 2.60 × 10⁸ m/s east. Do not contract both objects in Nancy’s frame.</p><p><b>Source note.</b> Interpret the premise as simultaneous emission in Nancy’s frame, correcting light travel time. Literal simultaneous viewing alone would not establish simultaneous emission.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>B: Minh sees Liam’s light first, moving toward it and away from Delta’s light.</td><td>1</td></tr><tr><td>b</td><td>Train proper length L₀ = 20.0 m.</td><td>1</td></tr><tr><td>b</td><td>Nancy’s contracted train length L = 10.0 m.</td><td>1</td></tr><tr><td>b</td><td>L/L₀ = √(1 − v²/c²) = 0.500; v/c = √0.750 = 0.866.</td><td>1</td></tr><tr><td>b</td><td>v = 2.60 × 10⁸ m s⁻¹ eastward.</td><td>1</td></tr></tbody></table></div>"}, {"target": "relativity-energy-focus-2", "sourceID": "PHY-BOOK-Q120", "label": "WATP 2023, imported exam-book question 1 (The Standard Model)", "title": "Pion rest energy to photons", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q120-01.jpg\" width=\"868\" height=\"1161\" alt=\"Original question 120, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q120-02.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 120, section 2: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q120-03.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 120, section 3: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q120-04.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 120, section 4: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 1 (The Standard Model)</b></p><p><b>Step 1.</b> Use parts (a)–(c) to connect rest mass and photon energy. The rest-mass unit MeV/c² already encodes E₀ = mc². Convert 135.0 MeV to joules: 135.0 × 10⁶ × 1.60 × 10⁻¹⁹ = 2.16 × 10⁻¹¹ J; divide by c² to obtain m = 2.40 × 10⁻²⁸ kg.</p><p><b>Step 2.</b> For a pion decaying at rest into two photons, momentum conservation requires opposite photon directions and equal energies. Each has E = E₀/2 = 1.08 × 10⁻¹¹ J. Then λ = hc/E = 1.84 × 10⁻¹⁴ m, in the gamma-ray region.</p><p><b>Step 3.</b> Extension: parts (d)–(f) use older-paper Standard Model accounting and the supplied quark information. Up plus anti-down has charge +2/3 + 1/3 = +1, while a quark–antiquark meson has baryon number zero and lepton number zero.</p><p><b>Step 4.</b> For π⁺ → μ⁺ + unknown, conservation requires neutral charge, baryon number zero and lepton number +1, balancing the antimuon’s −1. The unknown is a muon neutrino. This particle bookkeeping is separate from the assessed rest-energy calculation.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>m = [135.0 × 10⁶ × 1.60 × 10⁻¹⁹]/(3.00 × 10⁸)².</td><td>1</td></tr><tr><td>a</td><td>mπ₀ = 2.40 × 10⁻²⁸ kg.</td><td>1</td></tr><tr><td>b</td><td>For a pion at rest, two opposite photons each carry ½mc².</td><td>1</td></tr><tr><td>b</td><td>Eeach = 1.08 × 10⁻¹¹ J (67.5 MeV).</td><td>1</td></tr><tr><td>c</td><td>λ = hc/Eeach.</td><td>1</td></tr><tr><td>c</td><td>λ = 1.84 × 10⁻¹⁴ m.</td><td>1</td></tr><tr><td>c</td><td>Gamma radiation.</td><td>1</td></tr><tr><td>d</td><td>u + anti-d charges: +2/3 + +1/3 = +1 in units of e.</td><td>1</td></tr><tr><td>e</td><td>Pion baryon number = +1/3 − 1/3 = 0.</td><td>1</td></tr><tr><td>e</td><td>Pion lepton number = 0.</td><td>1</td></tr><tr><td>f</td><td>Unknown charge = 0.</td><td>1</td></tr><tr><td>f</td><td>Baryon number = 0.</td><td>1</td></tr><tr><td>f</td><td>Lepton number = +1, balancing antimuon μ⁺ lepton number −1.</td><td>1</td></tr><tr><td>f</td><td>Muon neutrino νμ; π⁺ → μ⁺ + νμ.</td><td>1</td></tr></tbody></table></div>"}, {"target": "electric-fields-focus-3", "sourceID": "PHY-BOOK-Q002", "label": "WATP 2023, imported exam-book question 2 (Electromagnetism)", "title": "Electric suspension of a negative charge", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q002-01.jpg\" width=\"868\" height=\"598\" alt=\"Original question 2, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 2 (Electromagnetism)</b></p><p><b>Step 1.</b> The source diagram shows no supporting string: treat the ball as held at rest by the electric field. Draw weight down and electric force up; zero acceleration requires their magnitudes to match.</p><p><b>Step 2.</b> Electric field direction is the force direction on a positive test charge. The ball is negative, so an upward electric force requires a downward field. Draw at least four straight parallel equally spaced downward arrows to represent a uniform field.</p><p><b>Step 3.</b> Convert 4.50 g to 4.50 × 10⁻³ kg and 7.00 µC to 7.00 × 10⁻⁶ C. Use |q|E = mg, so E = 0.00450 × 9.80 / 0.00000700 = 6.30 × 10³ N/C downward. The magnitude is positive; direction is written separately.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>At least four straight, parallel, equally spaced lines show a uniform vertical field.</td><td>1</td></tr><tr><td>a</td><td>Arrows point downwards: a negative charge experiences an upward electric force.</td><td>1</td></tr><tr><td>b</td><td>Equilibrium requires |q|E = mg.</td><td>1</td></tr><tr><td>b</td><td>E = (4.50 × 10⁻³ × 9.80)/(7.00 × 10⁻⁶).</td><td>1</td></tr><tr><td>b</td><td>E = 6.30 × 10³ N C⁻¹.</td><td>1</td></tr></tbody></table></div>"}, {"target": "magnetic-fields-focus-3", "sourceID": "PHY-BOOK-Q005", "label": "WATP 2023, imported exam-book question 5 (Electromagnetism)", "title": "Magnetic force on a transmission line", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q005-01.jpg\" width=\"868\" height=\"376\" alt=\"Original question 5, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 5 (Electromagnetism)</b></p><p><b>Step 1.</b> At the equator the simplified Earth field is horizontal toward magnetic north. A northeast conventional current makes 45° with that field; the force formula uses the angle between current and field.</p><p><b>Step 2.</b> Use force per length F/L = IB sinθ. Convert 31.0 µT to 31.0 × 10⁻⁶ T, then calculate (1.25 × 10³)(31.0 × 10⁻⁶)sin45° = 2.74 × 10⁻² N/m.</p><p><b>Step 3.</b> For direction, take east × north = up; only the eastward component of the northeast current contributes because the northward component is parallel to B. Thus force is upward under the stated current/field convention.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>—</td><td>Use F/L = IB sin θ.</td><td>1</td></tr><tr><td>—</td><td>The horizontal field points north; a NE current makes θ = 45°. Substitute I = 1.25 × 10³ A and B = 31.0 × 10⁻⁶ T.</td><td>1</td></tr><tr><td>—</td><td>F/L = 2.74 × 10⁻² N m⁻¹ (upward force).</td><td>1</td></tr></tbody></table></div>"}, {"target": "motors-focus-1", "sourceID": "PHY-BOOK-Q020", "label": "WATP 2021, imported exam-book question 20 (Electromagnetism)", "title": "DC motor torque and back emf", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q020-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 20, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2021, imported exam-book question 20 (Electromagnetism)</b></p><p><b>Step 1.</b> The image has north on the right and south on the left, so B points left. Use the required clockwise rotation viewed from BC to select the current circulation A → D → C → B → A; apply the current-force rule to opposite active sides.</p><p><b>Step 2.</b> The pictured coil plane is parallel to B, so its normal is perpendicular to B and torque is maximal. Area A = (0.100)² = 0.0100 m². τ = NBIA = 15 × 0.55 × 1.50 × 0.0100 = 0.124 N·m. Do not use the side length as the area.</p><p><b>Step 3.</b> Rotation changes flux and produces a back emf opposing the supply. Increasing speed increases back emf, reducing net coil voltage, current and torque. With mechanical friction and load ignored, current/torque approach zero as back emf approaches the supply; inertia sustains rotation. A loaded real motor retains torque to balance its load.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Current circulates A → D → C → B → A, giving clockwise rotation when viewed from BC.</td><td>1</td></tr><tr><td>b</td><td>Maximum torque τ = NBIA.</td><td>1</td></tr><tr><td>b</td><td>A = 0.100² = 0.0100 m²; substitute N = 15, B = 0.550 T and I = 1.50 A.</td><td>1</td></tr><tr><td>b</td><td>τ = 0.124 N m.</td><td>1</td></tr><tr><td>c</td><td>Rotation changes magnetic flux, inducing an emf opposing the applied supply (Lenz’s law).</td><td>1</td></tr><tr><td>c</td><td>As speed increases, back emf increases, so net voltage and current decrease.</td><td>1</td></tr><tr><td>c</td><td>In the ideal unloaded frictionless limit, back emf approaches the supply voltage and current/torque approach zero; inertia maintains rotation.</td><td>1</td></tr></tbody></table></div>"}, {"target": "induction-focus-1", "sourceID": "PHY-BOOK-Q001", "label": "WATP 2023, imported exam-book question 1 (Electromagnetism)", "title": "Rotating one loop: average emf", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q001-01.jpg\" width=\"868\" height=\"466\" alt=\"Original question 1, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 1 (Electromagnetism)</b></p><p><b>Step 1.</b> The drawing’s 50° is the angle of the loop plane above horizontal. With vertical B, the normal initially makes 50° with B; when the loop becomes horizontal the normal is parallel to B. Use the normal angle in Φ = BA cosθ.</p><p><b>Step 2.</b> The side length is 0.750 m, so A = 0.5625 m². Initial flux is 1.26 × 0.5625 cos50° = 0.456 Wb; final flux is 1.26 × 0.5625 = 0.709 Wb. The increase is approximately 0.253 Wb.</p><p><b>Step 3.</b> There is one loop, not an unstated multi-turn coil. Average emf magnitude is |ΔΦ|/Δt = 0.253/0.430 = 0.589 V. This is an average across the rotation, not necessarily the instantaneous or peak emf.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>—</td><td>Area A = 0.750² = 0.5625 m².</td><td>1</td></tr><tr><td>—</td><td>Initial flux Φᵢ = BA cos 50.0°; final flux Φf = BA.</td><td>1</td></tr><tr><td>—</td><td>|ε̄| = |ΔΦ|/Δt = 1.26 × 0.5625 × (1 − cos 50.0°)/0.430.</td><td>1</td></tr><tr><td>—</td><td>|ε̄| = 0.589 V.</td><td>1</td></tr></tbody></table></div>"}, {"target": "generators-focus-1", "sourceID": "PHY-BOOK-Q011", "label": "WATP 2022, imported exam-book question 11 (Electromagnetism)", "title": "Generator graph and uncertainty", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q011-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 11, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q011-02.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 11, section 2: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2022, imported exam-book question 11 (Electromagnetism)</b></p><p><b>Step 1.</b> The source graph plots peak voltage in mV against frequency in Hz. Choose a large triangle on the fitted line: gradient is approximately 1.5 mV/Hz = 1.5 × 10⁻³ V·s. Do not confuse millivolts with volts.</p><p><b>Step 2.</b> For a rotating coil εmax = NBAω = 2πNBAf. Therefore the graph slope is 2πNBA and B = slope/(2πNA). Convert coil dimensions to metres: A = 0.0800 × 0.0600 = 0.00480 m² with N = 15. This gives B ≈ 3.3 × 10⁻³ T.</p><p><b>Step 3.</b> Draw steepest and shallowest plausible lines compatible with the error bars, rather than connecting two arbitrary data points. Slopes about 1.9 and 1.2 mV/Hz give a half-range uncertainty in B about 0.0007 T. Report (3.3 ± 0.7) × 10⁻³ T; defensible graph readings may vary.</p><p><b>Source note.</b> Printed total is 6 marks; the displayed subparts/criteria total 7 marks, which is used in this assessment.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Gradient ≈ 1.5 × 10⁻³ V Hz⁻¹ = 1.5 × 10⁻³ V s from a large triangle on the best-fit line.</td><td>1</td></tr><tr><td>a</td><td>εmax = NBA(2πf), so B = gradient/(2πNA), A = 0.0800 × 0.0600 m² and N = 15.</td><td>1</td></tr><tr><td>a</td><td>B ≈ 3.3 × 10⁻³ T (two significant figures).</td><td>1</td></tr><tr><td>b</td><td>Draw the steepest and shallowest plausible straight lines consistent with the vertical error bars.</td><td>1</td></tr><tr><td>b</td><td>Calculate their gradients: approximately 1.9 and 1.2 mV Hz⁻¹; accept defensible readings from the source plot.</td><td>1</td></tr><tr><td>b</td><td>ΔB = (Bmax − Bmin)/2 ≈ 0.0007 T, or an equivalent maximum deviation from the best-fit value.</td><td>1</td></tr><tr><td>b</td><td>Report B ≈ (3.3 ± 0.7) × 10⁻³ T with B to two significant figures and uncertainty to one. Accept graph-resolution variation.</td><td>1</td></tr></tbody></table></div>"}, {"target": "transformers-focus-2", "sourceID": "PHY-BOOK-Q003", "label": "WATP 2023, imported exam-book question 3 (Electromagnetism)", "title": "Transmission loss before transformer ratio", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q003-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 3, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 3 (Electromagnetism)</b></p><p><b>Step 1.</b> Work through the stages in order. First determine transmission-line current at the generator: I = P/V = 330 × 10⁶/(265 × 10³) = 1245 A. The source uses a line resistance of 0.225 Ω per kilometre across 40.0 km, so R = 9.00 Ω.</p><p><b>Step 2.</b> Voltage lost along that line is IR = 11208 V. Thus the receiving transformer primary has Vp = 265000 − 11208 = 253792 V ≈ 254 kV. Do not directly use the generator voltage in the transformer turns ratio.</p><p><b>Step 3.</b> An ideal transformer gives Np/Ns = Vp/Vs. With Ns = 100 and Vs = 15000 V, Np = 100 × 253792/15000 ≈ 1690 turns. The paper explicitly permits 260 kV if part (a) was unfinished; that gives about 1730 turns as consistent follow-through.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Transmission current I = P/V = 330 × 10⁶/(265 × 10³) = 1.245 × 10³ A.</td><td>1</td></tr><tr><td>a</td><td>Line resistance R = 40.0 × 0.225 = 9.00 Ω.</td><td>1</td></tr><tr><td>a</td><td>Voltage loss ΔV = IR = 1.12 × 10⁴ V.</td><td>1</td></tr><tr><td>a</td><td>Primary voltage Vp = 265000 − ΔV.</td><td>1</td></tr><tr><td>a</td><td>Vp = 2.54 × 10⁵ V = 254 kV.</td><td>1</td></tr><tr><td>b</td><td>Np/Ns = Vp/Vs, so Np = 100 Vp/15000.</td><td>1</td></tr><tr><td>b</td><td>Np ≈ 1.69 × 10³ turns. Using the permitted 260 kV gives 1.73 × 10³ turns; accept consistent follow-through.</td><td>1</td></tr></tbody></table></div>"}, {"target": "quantum-focus-3", "sourceID": "PHY-BOOK-Q101", "label": "WATP 2023, imported exam-book question 1 (Quantum Theory)", "title": "Sodium energy level from emitted light", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q101-01.jpg\" width=\"868\" height=\"1124\" alt=\"Original question 101, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q101-02.jpg\" width=\"868\" height=\"40\" alt=\"Original question 101, section 2: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 1 (Quantum Theory)</b></p><p><b>Step 1.</b> The zero-energy ionisation limit corresponds to n = ∞. The depicted photon comes from a downward n = 3 to n = 1 transition, so its positive energy is E₃ − E₁.</p><p><b>Step 2.</b> Convert 589.6 nm to 589.6 × 10⁻⁹ m. Eγ = hc/λ = 3.37 × 10⁻¹⁹ J. Divide by 1.60 × 10⁻¹⁹ J/eV to obtain 2.11 eV.</p><p><b>Step 3.</b> The lower level is −5.14 eV. Thus E₃ = E₁ + Eγ = −5.14 + 2.11 = −3.03 eV. A downward transition loses energy, so the starting level must be less negative than the final level; reversing the sign would fail that check.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>n = ∞ at the 0 eV ionization limit.</td><td>1</td></tr><tr><td>b</td><td>For the downward transition Eγ = E₃ − E₁.</td><td>1</td></tr><tr><td>b</td><td>Eγ = hc/λ.</td><td>1</td></tr><tr><td>b</td><td>Use λ = 589.6 × 10⁻⁹ m, giving Eγ = 3.37 × 10⁻¹⁹ J.</td><td>1</td></tr><tr><td>b</td><td>Convert to eV: Eγ = 2.11 eV.</td><td>1</td></tr><tr><td>b</td><td>E₃ = −5.14 + 2.11 = −3.03 eV.</td><td>1</td></tr></tbody></table></div>"}, {"target": "young-double-slit", "sourceID": "PHY-BOOK-Q108", "label": "WATP 2023, imported exam-book question 1 (Quantum Theory)", "title": "Double-slit graph investigation", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q108-01.jpg\" width=\"868\" height=\"1161\" alt=\"Original question 108, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q108-02.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 108, section 2: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q108-03.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 108, section 3: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q108-04.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 108, section 4: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 1 (Quantum Theory)</b></p><p><b>Step 1.</b> Extension/data interpretation: use the equation and measurement convention printed in this older source, y = λmL/d. Overlapping coherent waves interfere: integer-wavelength path differences give maxima and half-integer differences give minima.</p><p><b>Step 2.</b> Complete the table with 1/(0.00800 × 10⁻³) = 1.25 × 10⁵ m⁻¹ and missing mean y = (0.0198 + 0.0192)/2 = 0.0195 m. Plot y vertically and 1/d horizontally; a scaled horizontal axis must retain its ×10⁵ factor.</p><p><b>Step 3.</b> A best-fit gradient is about 2.30 × 10⁻⁷ m². Since the supplied equation says gradient = λmL, divide by mL = 3 × 1.10 to obtain λ ≈ 6.98 × 10⁻⁸ m. Units: metres divided by inverse metres gives m² for the slope.</p><p><b>Step 4.</b> Source-model caution: the page calls y spacing between successive fringes, but also uses m = 3, and its numerical result is ultraviolet rather than ordinary visible laser light. We follow its explicitly supplied relation for this walkthrough; do not generalise this inconsistency. Adjacent-fringe spacing normally obeys Δy = λL/d without m. Higher frequency reduces wavelength and fringe spacing in either consistent model.</p><p><b>Source note.</b> The prose calls y “average fringe distance” but the supplied equation and m = 3 treat it as central-to-third-maximum displacement. The intended key uses m = 3; accept λ ≈ 2.09 × 10⁻⁷ m if y is explicitly interpreted as adjacent-fringe spacing (m = 1).</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Light diffracts through the narrow slits, producing overlapping coherent waves.</td><td>1</td></tr><tr><td>a</td><td>Constructive interference at integer-wavelength path differences creates bright fringes; destructive interference at half-integer differences creates dark fringes.</td><td>1</td></tr><tr><td>a</td><td>Interference/superposition is evidence of wave behaviour.</td><td>1</td></tr><tr><td>b</td><td>At d = 0.00800 × 10⁻³ m, 1/d = 1.25 × 10⁵ m⁻¹.</td><td>1</td></tr><tr><td>b</td><td>Missing mean y = (0.0198 + 0.0192)/2 = 0.0195 m.</td><td>1</td></tr><tr><td>c</td><td>Label axes y (m) and 1/d (m⁻¹ or ×10⁵ m⁻¹), with suitable scales.</td><td>1</td></tr><tr><td>c</td><td>Plot all five points accurately.</td><td>2</td></tr><tr><td>c</td><td>Draw a straight best-fit line.</td><td>1</td></tr><tr><td>d</td><td>Show a large gradient triangle on the best-fit line.</td><td>1</td></tr><tr><td>d</td><td>Gradient Δy/Δ(1/d) ≈ 2.30 × 10⁻⁷ m².</td><td>1</td></tr><tr><td>d</td><td>State units m² and include the ×10⁵ axis factor.</td><td>1</td></tr><tr><td>e</td><td>From the given y = λmL/d, slope = λmL.</td><td>1</td></tr><tr><td>e</td><td>Use m = 3 and L = 1.10 m: λ = slope/(3 × 1.10).</td><td>1</td></tr><tr><td>e</td><td>λ ≈ 6.98 × 10⁻⁸ m ≈ 70 nm; accept graphical variation.</td><td>1</td></tr><tr><td>f</td><td>Higher frequency gives shorter wavelength because c = fλ.</td><td>1</td></tr><tr><td>f</td><td>Fringe spacing decreases, so fringes are closer together.</td><td>1</td></tr></tbody></table></div>"}, {"target": "led-quantum-emission", "sourceID": "PHY-BOOK-Q109", "label": "WATP 2021, imported exam-book question 2 (Quantum Theory)", "title": "LED graph to Planck constant", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q109-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 109, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q109-02.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 109, section 2: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q109-03.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 109, section 3: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2021, imported exam-book question 2 (Quantum Theory)</b></p><p><b>Step 1.</b> Extension supplied model: approximate electrical energy per electron eV₀ as photon energy hc/λ. Real LEDs have material-dependent behaviour; varying voltage on one LED does not generally tune its emitted photon energy as the source wording suggests.</p><p><b>Step 2.</b> Equating energies gives V₀ = (hc/e)(1/λ). For the red LED, 695 nm is 695 × 10⁻⁹ m, so 1/λ = 1.44 × 10⁶ m⁻¹. Plot V₀ on y and inverse wavelength on x, including the ×10⁶ axis multiplier.</p><p><b>Step 3.</b> The best-fit slope is approximately 1.24 × 10⁻⁶ V·m. Identify this with hc/e, then rearrange h = slope × e/c = (1.24 × 10⁻⁶)(1.60 × 10⁻¹⁹)/(3.00 × 10⁸) = 6.61 × 10⁻³⁴ J·s, close to accepted h. Graph-based answers around 6.6 × 10⁻³⁴ are appropriate; do not demand one exact gradient.</p><p><b>Source note.</b> The LED model is approximate: increased voltage above threshold mainly changes current/output, not photon energy continuously. Use the threshold relation instructed.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Electrical energy qₑV₀ equals emitted photon energy hc/λ in the stated approximation.</td><td>1</td></tr><tr><td>a</td><td>Rearrange V₀ = hc/(qₑλ).</td><td>1</td></tr><tr><td>b</td><td>For red, 1/λ = 1/(695 × 10⁻⁹) = 1.44 × 10⁶ m⁻¹.</td><td>1</td></tr><tr><td>c</td><td>Label axes V₀ (V) and 1/λ (m⁻¹ or ×10⁶ m⁻¹), with suitable scales.</td><td>1</td></tr><tr><td>c</td><td>Plot all four points accurately.</td><td>2</td></tr><tr><td>c</td><td>Draw a straight best-fit line.</td><td>1</td></tr><tr><td>d</td><td>Show a large best-fit gradient triangle.</td><td>1</td></tr><tr><td>d</td><td>Slope = ΔV₀/Δ(1/λ).</td><td>1</td></tr><tr><td>d</td><td>Slope ≈ 1.24 × 10⁻⁶ V m.</td><td>1</td></tr><tr><td>d</td><td>Include V m units and correct ×10⁶ conversion; accept graph variation.</td><td>1</td></tr><tr><td>e</td><td>Slope = hc/qₑ.</td><td>1</td></tr><tr><td>e</td><td>h = slope × qₑ/c.</td><td>1</td></tr><tr><td>e</td><td>Use qₑ = 1.60 × 10⁻¹⁹ C and c = 3.00 × 10⁸ m s⁻¹.</td><td>1</td></tr><tr><td>e</td><td>h ≈ 6.63 × 10⁻³⁴ J s; accept consistent graphical follow-through.</td><td>1</td></tr></tbody></table></div>"}, {"target": "cosmology-focus-2", "sourceID": "PHY-BOOK-Q116", "label": "WATP 2023, imported exam-book question 1 (Big Bang Theory)", "title": "Blueshift versus Hubble-law distance", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q116-01.jpg\" width=\"868\" height=\"1124\" alt=\"Original question 116, section 1: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 1 (Big Bang Theory)</b></p><p><b>Step 1.</b> Separate the observed case in part (a) from the hypothetical receding case in part (b). Blueshift means approaching radial motion, whereas large-scale expansion generally predicts redshift for distant galaxies. Peculiar velocities can oppose expansion; one blueshift alone does not disprove Big Bang cosmology.</p><p><b>Step 2.</b> Part (b) explicitly asks about the same magnitude as a positive recessional speed. Convert 1.03 × 10⁶ m/s to 1030 km/s to match H₀ = 73.8 km/s/Mpc. Then d = v/H₀ = 1030/73.8 = 13.96 Mpc.</p><p><b>Step 3.</b> Convert with 1 Mpc = 3.26 × 10⁶ ly: d = 4.55 × 10⁷ ly. This is a Hubble-law distance for hypothetical recession, not a negative distance inferred directly from the observed blueshift.</p><p><b>Source note.</b> H₀ is the supplied historical value. Positive Hubble distance applies to the hypothetical recession, not directly to the actual blueshift.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Blueshift means the object approaches along the line of sight.</td><td>1</td></tr><tr><td>a</td><td>Cosmic expansion generally makes sufficiently distant galaxies recede/redshift according to Hubble’s law.</td><td>1</td></tr><tr><td>a</td><td>It appears contrary to the simple expansion expectation, but peculiar motion can cause blueshift and does not alone disprove Big Bang cosmology.</td><td>1</td></tr><tr><td>b</td><td>d = v/H₀ with v = 1030 km s⁻¹.</td><td>1</td></tr><tr><td>b</td><td>d = 1030/73.8 = 13.96 Mpc.</td><td>1</td></tr><tr><td>b</td><td>1 Mpc ≈ 3.26 × 10⁶ ly gives d = 4.55 × 10⁷ ly for the hypothetical positive recessional speed.</td><td>1</td></tr></tbody></table></div>"}, {"target": "magnetic-fields-focus-2", "sourceID": "PHY-BOOK-Q043", "label": "WATP 2022, imported exam-book question 9 (Electromagnetism)", "title": "Mass spectrometer stages", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q043-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 43, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q043-02.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 43, section 2: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q043-03.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 43, section 3: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2022, imported exam-book question 9 (Electromagnetism)</b></p><p><b>Step 1.</b> Use a new model for each stage. Stage 1 accelerates a positive ion: qV = ½mv². With m = 3.34 × 10⁻²⁷ kg, v = 6.19 × 10⁵ m/s and q = 1.60 × 10⁻¹⁹ C, V = 4.00 × 10³ V.</p><p><b>Step 2.</b> In the image stage 2 has a positive upper plate and negative lower plate, so E and the positive-ion electric force point down. A rightward positive beam needs upward magnetic force to cancel it: B points into the page. Balance qE = qvB, giving v = E/B.</p><p><b>Step 3.</b> Stage 3 bends the rightward beam downward; its B must point out of the page. Magnetic force supplies inward acceleration: qvB = mv²/r. A vacuum avoids scattering and energy-transfer collisions; slowing ions have smaller r = mv/(qB).</p><p><b>Step 4.</b> For a complete circle, f = v/(2πr). Substitute r = mv/(qB) to obtain f = qB/(2πm), independent of speed in the nonrelativistic model. B = 1.20 T gives f = 9.15 × 10⁶ Hz. The accelerating field changes speed; the bending magnetic field alone does no work.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Electric potential energy qV becomes kinetic energy ½mv².</td><td>1</td></tr><tr><td>a</td><td>V = mv²/(2q).</td><td>1</td></tr><tr><td>a</td><td>Use m = 3.34 × 10⁻²⁷ kg, v = 6.19 × 10⁵ m s⁻¹ and q = 1.60 × 10⁻¹⁹ C.</td><td>1</td></tr><tr><td>a</td><td>V = 4.00 × 10³ V.</td><td>1</td></tr><tr><td>b(i)</td><td>Into the page, so the magnetic force is upward and balances the downward electric force.</td><td>1</td></tr><tr><td>b(ii)</td><td>Straight motion requires qE = qvB.</td><td>1</td></tr><tr><td>b(ii)</td><td>Hence v = E/B (or E = vB).</td><td>1</td></tr><tr><td>c(i)</td><td>Out of the page: the rightward positive-ion beam bends downward.</td><td>1</td></tr><tr><td>c(ii)</td><td>A vacuum prevents collisions with gas molecules.</td><td>1</td></tr><tr><td>c(ii)</td><td>Gas collisions scatter ions and transfer kinetic energy, reducing their speed.</td><td>1</td></tr><tr><td>c(ii)</td><td>The radius r = mv/(qB) decreases with speed and paths become scattered/inward-curving rather than the precise original arc.</td><td>1</td></tr><tr><td>d</td><td>qvB = mv²/r.</td><td>1</td></tr><tr><td>d</td><td>r = mv/(qB).</td><td>1</td></tr><tr><td>d</td><td>f = v/(2πr).</td><td>1</td></tr><tr><td>d</td><td>Substitution gives f = qB/(2πm), independent of speed in the nonrelativistic model.</td><td>1</td></tr><tr><td>e</td><td>f = (1.60 × 10⁻¹⁹ × 1.20)/(2π × 3.34 × 10⁻²⁷).</td><td>1</td></tr><tr><td>e</td><td>f = 9.15 × 10⁶ Hz.</td><td>1</td></tr></tbody></table></div>"}, {"target": "black-body-radiation", "sourceID": "PHY-BOOK-Q123", "label": "WATP 2023, imported exam-book question 3 (Comprehension)", "title": "Black-hole comprehension across models", "images": "<img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q123-01.jpg\" width=\"868\" height=\"1191\" alt=\"Original question 123, section 1: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q123-02.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 123, section 2: diagrams and student response space\" loading=\"lazy\"><img style=\"display:block;width:100%;height:auto;max-width:100%;background:white;margin:12px 0\" src=\"assets/physics/exam-import/exam-book-2020-2023/Q123-03.jpg\" width=\"868\" height=\"1255\" alt=\"Original question 123, section 3: diagrams and student response space\" loading=\"lazy\">", "solution": "<div class=\"pp-page\"><p><b>WATP 2023, imported exam-book question 3 (Comprehension)</b></p><p><b>Step 1.</b> Extension comprehension: treat the article as supplied context, not a precise general-relativistic description of a black hole. Its event-horizon escape-speed analogy and Newtonian orbital estimate are approximations.</p><p><b>Step 2.</b> For part (a), cooling lowers temperature; Wien’s law predicts a longer peak wavelength and thermal power decreases. A shift toward lower-energy radiation is consistent with cooling under a black-body approximation. For (b), polarisation restricts transverse electric-field oscillation directions and supports wave behaviour.</p><p><b>Step 3.</b> For (c) use the stated circular estimate: r = 0.4 AU = 6.0 × 10¹⁰ m and T = 70 × 60 = 4200 s. v = 2πr/T = 8.98 × 10⁷ m/s = 0.299c. For (d), M = 4π²r³/(GT²) ≈ 7.25 × 10³⁶ kg ≈ 3.64 million solar masses. These are the article’s Newtonian estimates, not an exact strong-field orbit analysis.</p><p><b>Step 4.</b> Part (e) is explicitly a separate inertial-frame timing scenario. Treat 70 min as the moving clock’s proper interval; γ = 1/√(1 − 0.30²) = 1.048, so Earth measures γ × 70 = 73.4 min. Do not interpret this as a complete timing model for an accelerating orbit near the black hole.</p><p><b>Source note.</b> The black-body/Kepler calculations are the question’s approximations; real accretion emission and strong gravity require more detailed models. “Viewed” duration is interpreted as frame-measured, not visual Doppler timing.</p><p><b>Teacher-created marking guide.</b> This explanation and table are authored for the imported question; they are not a supplied publisher marking key. Accept equivalent valid methods and consistent follow-through.</p><table class=\"pf-marking\"><thead><tr><th>Part</th><th>Teacher-created answer / marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>a</td><td>Cooling reduces the temperature of the emitting material.</td><td>1</td></tr><tr><td>a</td><td>For a black-body approximation, peak wavelength increases as temperature falls (Wien’s law).</td><td>1</td></tr><tr><td>a</td><td>A shift from X-rays to infrared/radio corresponds to lower photon energies/longer wavelengths, consistent with cooling; total thermal power also falls.</td><td>1</td></tr><tr><td>b</td><td>Polarized radiation has electric-field oscillations preferentially restricted to one direction/plane perpendicular to propagation.</td><td>1</td></tr><tr><td>b</td><td>Unpolarized radiation has many transverse oscillation directions.</td><td>1</td></tr><tr><td>b</td><td>Polarization is evidence of transverse wave behaviour, rather than proof of light’s particle nature.</td><td>1</td></tr><tr><td>c</td><td>Orbital radius r = 0.4 AU = 6.0 × 10¹⁰ m.</td><td>1</td></tr><tr><td>c</td><td>Period T = 70 × 60 = 4200 s.</td><td>1</td></tr><tr><td>c</td><td>v = 2πr/T = 8.98 × 10⁷ m s⁻¹.</td><td>1</td></tr><tr><td>c</td><td>v/c = 0.299 ≈ 30%.</td><td>1</td></tr><tr><td>d</td><td>Kepler relation M = 4π²r³/(GT²).</td><td>1</td></tr><tr><td>d</td><td>Use r = 6.0 × 10¹⁰ m and T = 4200 s.</td><td>1</td></tr><tr><td>d</td><td>M ≈ 7.25 × 10³⁶ kg.</td><td>1</td></tr><tr><td>d</td><td>M/MSun ≈ 3.64 × 10⁶ solar masses, more than 3.5 million.</td><td>1</td></tr><tr><td>e</td><td>Treat 70 min as proper duration in the moving frame.</td><td>1</td></tr><tr><td>e</td><td>γ = 1/√(1 − 0.300²) = 1.048.</td><td>1</td></tr><tr><td>e</td><td>Earth-frame duration Δt = γΔt₀.</td><td>1</td></tr><tr><td>e</td><td>Δt = 73.4 min.</td><td>1</td></tr></tbody></table></div>"}];
for(const x of cases){const entry=C.registry.find(s=>s.id===x.target);if(!entry)throw new Error('Missing exam walkthrough target '+x.target);const s=entry.spec||entry;if(!s.pages)throw new Error('No pages on walkthrough target '+x.target);s.pages.push({chapter:3,title:'Past exam: '+x.title,type:'practice',html:'<div class="pp-page"><p><b>'+H.esc(x.label)+'</b></p><p>Read the original source and attempt the question before moving to the explained method. Source diagrams and labels are retained.</p>'+x.images.replace(/<img\b[^>]*>/g,image=>'<a href="'+image.match(/src="([^"]+)"/)[1]+'" target="_blank" rel="noopener" aria-label="Open original exam image at full size">'+image+'</a>')+'<p>Open an image to read it at full size.</p>'+H.paper('Your annotated diagram, reasoning and working')+'</div>'},{chapter:3,title:'Explained past exam: '+x.title,type:'worked',html:x.solution});}
window.PhysicsYear12ExamWalkthroughs={questions:cases.length,sections:cases.length*2,sources:cases.map(x=>({id:x.sourceID,target:x.target,label:x.label}))};
})();
